var output=Path.GetFullPath(args.Single(a=>a.StartsWith("--output=",StringComparison.Ordinal))[9..]);
if(File.Exists(output))throw new IOException("Retain previous output.");
var checks=new List<object>();var passed=0;var failed=0;
void Require(bool value){if(!value)throw new InvalidOperationException("Contract assertion failed.");}
async Task Check(string name,Func<Task> body){try{await body().WaitAsync(TimeSpan.FromSeconds(15));checks.Add(new{name,passed=true});passed++;}catch(Exception error){checks.Add(new{name,passed=false,error=error.GetType().FullName,message=error.Message});failed++;}}
async Task<T> Expected<T>(Func<Task> body)where T:Exception{try{await body();}catch(T error){return error;}throw new InvalidOperationException("Expected exception was not observed.");}
void Invalid<T>(Action body)where T:Exception{try{body();}catch(T){return;}throw new InvalidOperationException("Expected exception was not observed.");}
var observed=DateTimeOffset.Parse("2026-11-21T00:00:00Z");
TenantChangeAuditOutboxStatus Status(TenantId? tenant=null)=>new(tenant??new("A"),observed,3,2,1,1,4,observed.AddMinutes(-1));
TenantChangeAuditOutboxStatusReader Reader(Source source,TimeSpan? budget=null)=>TenantChangeAuditOutboxStatusReader.Activate(true,()=>source,budget)!;

await Check("coherent snapshot preserves each aggregate and provider timestamp",()=>{var s=Status();Require(s.Tenant.Equals(new TenantId("A"))&&s.ObservedAtUtc==observed&&s.Pending==3&&s.Available==2&&s.Claimed==1&&s.ExpiredClaims==1&&s.Delivered==4&&s.OldestPendingAtUtc==observed.AddMinutes(-1));return Task.CompletedTask;});
await Check("empty pending set allows delivered records but has no oldest timestamp",()=>{var s=new TenantChangeAuditOutboxStatus(new("A"),observed,0,0,0,0,9);Require(s.Pending==0&&s.Delivered==9&&s.OldestPendingAtUtc is null);return Task.CompletedTask;});
await Check("provider UTC offsets normalize without changing instants",()=>{var time=observed.ToOffset(TimeSpan.FromHours(7));var s=new TenantChangeAuditOutboxStatus(new("A"),time,1,1,0,0,0,time.AddTicks(-1));Require(s.ObservedAtUtc.Offset==TimeSpan.Zero&&s.OldestPendingAtUtc!.Value.Offset==TimeSpan.Zero&&s.ObservedAtUtc==observed&&s.OldestPendingAtUtc==observed.AddTicks(-1));return Task.CompletedTask;});
await Check("oldest timestamp may equal observed instant",()=>{Require(new TenantChangeAuditOutboxStatus(new("A"),observed,1,0,1,0,0,observed).OldestPendingAtUtc==observed);return Task.CompletedTask;});
await Check("null tenant rejected",()=>{Invalid<ArgumentNullException>(()=>new TenantChangeAuditOutboxStatus(null!,observed,0,0,0,0,0));return Task.CompletedTask;});
foreach(var slot in Enumerable.Range(0,5))await Check("negative aggregate rejected field "+slot,()=>{var n=new long[]{3,2,1,1,4};n[slot]=-1;Invalid<ArgumentException>(()=>new TenantChangeAuditOutboxStatus(new("A"),observed,n[0],n[1],n[2],n[3],n[4],observed));return Task.CompletedTask;});
foreach(var shape in new[]{new long[]{2,3,0,0,0},new long[]{3,1,1,0,0},new long[]{3,1,3,0,0},new long[]{3,2,1,3,0},new long[]{long.MaxValue,long.MaxValue,long.MaxValue,0,0}})
await Check("incoherent aggregate partition rejected "+string.Join('/',shape),()=>{Invalid<ArgumentException>(()=>new TenantChangeAuditOutboxStatus(new("A"),observed,shape[0],shape[1],shape[2],shape[3],shape[4],observed));return Task.CompletedTask;});
await Check("max available and delivered counts do not overflow a fabricated total",()=>{var s=new TenantChangeAuditOutboxStatus(new("A"),observed,long.MaxValue,long.MaxValue,0,long.MaxValue,long.MaxValue,observed);Require(s.Pending==long.MaxValue&&s.Delivered==long.MaxValue);return Task.CompletedTask;});
await Check("max claimed partition is valid without overflowing addition",()=>{var s=new TenantChangeAuditOutboxStatus(new("A"),observed,long.MaxValue,0,long.MaxValue,0,0,observed);Require(s.Claimed==long.MaxValue);return Task.CompletedTask;});
await Check("nonempty pending set must have oldest timestamp",()=>{Invalid<ArgumentException>(()=>new TenantChangeAuditOutboxStatus(new("A"),observed,1,1,0,0,0));return Task.CompletedTask;});
await Check("empty pending set cannot invent oldest timestamp",()=>{Invalid<ArgumentException>(()=>new TenantChangeAuditOutboxStatus(new("A"),observed,0,0,0,0,0,observed));return Task.CompletedTask;});
await Check("oldest later than provider observation rejected",()=>{Invalid<ArgumentException>(()=>new TenantChangeAuditOutboxStatus(new("A"),observed,1,1,0,0,0,observed.AddTicks(1)));return Task.CompletedTask;});
await Check("aggregate DTO surface is sealed readonly and contains no payload or identity",()=>{var t=typeof(TenantChangeAuditOutboxStatus);Require(t.IsSealed&&t.GetFields().Length==0);var props=t.GetProperties();Require(props.Length==8&&props.All(p=>p.SetMethod is null));Require(props.Select(p=>p.Name).Order().SequenceEqual(new[]{"Tenant","ObservedAtUtc","Pending","Available","Claimed","ExpiredClaims","Delivered","OldestPendingAtUtc"}.Order()));var json=JsonSerializer.Serialize(Status());Require(!json.Contains("Receipt",StringComparison.Ordinal)&&!json.Contains("Principal",StringComparison.Ordinal)&&!json.Contains("Fields",StringComparison.Ordinal));return Task.CompletedTask;});
await Check("disabled skips poison factory and invalid optional budget",()=>{var factories=0;Require(TenantChangeAuditOutboxStatusReader.Activate(false,()=>{factories++;throw new IOException();},TimeSpan.MinValue) is null&&factories==0);Require(TenantChangeAuditOutboxStatusReader.Activate(false) is null);return Task.CompletedTask;});
await Check("enabled requires configured source factory",()=>{Invalid<ArgumentNullException>(()=>TenantChangeAuditOutboxStatusReader.Activate(true));return Task.CompletedTask;});
foreach(var bound in new[]{TimeSpan.Zero,TimeSpan.FromTicks(-1),TimeSpan.FromMinutes(1).Add(TimeSpan.FromTicks(1))})await Check("invalid budget rejected before source construction "+bound.Ticks,()=>{var calls=0;Invalid<ArgumentOutOfRangeException>(()=>TenantChangeAuditOutboxStatusReader.Activate(true,()=>{calls++;return new Source();},bound));Require(calls==0);return Task.CompletedTask;});
await Check("null source result from factory rejects activation",()=>{Invalid<ArgumentException>(()=>TenantChangeAuditOutboxStatusReader.Activate(true,()=>null!));return Task.CompletedTask;});
await Check("activation is once and lazy with no status read",()=>{var source=new Source();var calls=0;Require(TenantChangeAuditOutboxStatusReader.Activate(true,()=>{calls++;return source;},TimeSpan.FromMinutes(1)) is not null&&calls==1&&source.Calls==0);return Task.CompletedTask;});
await Check("null checked context rejected before source",async()=>{var source=new Source();await Expected<ArgumentNullException>(()=>Reader(source).ReadAsync(null!).AsTask());Require(source.Calls==0);});
await Check("pre-cancelled caller skips source and preserves original token",async()=>{var f=new Fixture();var source=new Source();using var ct=new CancellationTokenSource();ct.Cancel();await f.Run(async c=>{var e=await Expected<OperationCanceledException>(()=>Reader(source).ReadAsync(c,ct.Token).AsTask());Require(e.CancellationToken==ct.Token);});Require(source.Calls==0);});
foreach(var operation in new[]{"outbox.relay","audit.history","document.update","inspect.wrong-kind","inspect.wrong-id"})await Check("unrelated checked permission cannot inspect "+operation,async()=>{var f=new Fixture();var source=new Source();await f.Run(c=>Expected<TenantAccessDeniedException>(()=>Reader(source).ReadAsync(c).AsTask()),operation);Require(source.Calls==0);});
await Check("expired context rejected before source",async()=>{var f=new Fixture();var source=new Source();await f.Run(async c=>{f.Clock.Advance(TimeSpan.FromMinutes(2));await Expected<TenantAccessDeniedException>(()=>Reader(source).ReadAsync(c).AsTask());});Require(source.Calls==0);});
await Check("retained disposed context rejected despite configured reader and valid DTO",async()=>{var f=new Fixture();var source=new Source();TenantOperationContext? held=null;await f.Run(c=>{held=c;return Task.CompletedTask;});await Expected<TenantAccessDeniedException>(()=>Reader(source).ReadAsync(held!).AsTask());Require(source.Calls==0);});
await Check("valid inspect scope reads exact tenant and returns immutable source observation",async()=>{var f=new Fixture();var status=Status();var source=new Source{Handler=(_,_)=>ValueTask.FromResult(status)};await f.Run(async c=>{var result=await Reader(source).ReadAsync(c);Require(ReferenceEquals(result,status)&&source.LastToken.CanBeCanceled);});Require(source.Calls==1&&source.Tenants.Single().Value=="A");});
await Check("compatible inspect operation name may be project selected",async()=>{var f=new Fixture();var source=new Source();await f.Run(async c=>{Require((await Reader(source).ReadAsync(c)).Tenant.Equals(c.Tenant));},"custom.status");Require(source.Calls==1);});
await Check("foreign tenant provider observation cannot escape",async()=>{var f=new Fixture();var source=new Source{Handler=(_,_)=>ValueTask.FromResult(Status(new("B")))};await f.Run(c=>Expected<TenantAccessDeniedException>(()=>Reader(source).ReadAsync(c).AsTask()));Require(source.Calls==1);});
await Check("null provider observation is a source contract fault",async()=>{var f=new Fixture();var source=new Source{Handler=(_,_)=>ValueTask.FromResult<TenantChangeAuditOutboxStatus>(null!)};await f.Run(c=>Expected<InvalidOperationException>(()=>Reader(source).ReadAsync(c).AsTask()));Require(source.Calls==1);});
await Check("source expiry invalidates result after asynchronous read",async()=>{var f=new Fixture();var source=new Source{Handler=async(tenant,_)=>{await Task.Yield();f.Clock.Advance(TimeSpan.FromMinutes(2));return Status(tenant);}};await f.Run(c=>Expected<TenantAccessDeniedException>(()=>Reader(source).ReadAsync(c).AsTask()));Require(source.Calls==1);});
await Check("provider clock facts are not compared to client clock for freshness",async()=>{var f=new Fixture();var future=f.Clock.Now.AddYears(20);var source=new Source{Handler=(tenant,_)=>ValueTask.FromResult(new TenantChangeAuditOutboxStatus(tenant,future,1,1,0,0,0,future.AddDays(-2)))};await f.Run(async c=>{Require((await Reader(source).ReadAsync(c)).ObservedAtUtc==future);});});
await Check("reader does not cache previous snapshots or authority",async()=>{var f=new Fixture();var source=new Source();var reader=Reader(source);await f.Run(async c=>{Require((await reader.ReadAsync(c)).Pending==3);source.Handler=(tenant,_)=>ValueTask.FromResult(new TenantChangeAuditOutboxStatus(tenant,observed,0,0,0,0,5));Require((await reader.ReadAsync(c)).Pending==0);});Require(source.Calls==2);});
await Check("unexpected source error remains the original exception",async()=>{var f=new Fixture();var failure=new IOException("Controlled source failure.");var source=new Source{Handler=(_,_)=>throw failure};await f.Run(async c=>{Require(ReferenceEquals(await Expected<IOException>(()=>Reader(source).ReadAsync(c).AsTask()),failure));});});
await Check("unrelated provider cancellation is not fabricated caller cancellation",async()=>{var f=new Fixture();using var unrelated=new CancellationTokenSource();unrelated.Cancel();var failure=new OperationCanceledException(unrelated.Token);var source=new Source{Handler=(_,_)=>throw failure};await f.Run(async c=>{var e=await Expected<OperationCanceledException>(()=>Reader(source).ReadAsync(c).AsTask());Require(ReferenceEquals(e,failure)&&e.CancellationToken==unrelated.Token);});});
await Check("cooperative caller cancellation is linked yet reports original caller token",async()=>{var f=new Fixture();using var caller=new CancellationTokenSource();var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var source=new Source{Handler=async(tenant,ct)=>{entered.TrySetResult();await Task.Delay(Timeout.InfiniteTimeSpan,ct);return Status(tenant);}};await f.Run(async c=>{var pending=Reader(source).ReadAsync(c,caller.Token).AsTask();try{await entered.Task;Require(source.LastToken!=caller.Token);caller.Cancel();var e=await Expected<OperationCanceledException>(()=>pending);Require(e.CancellationToken==caller.Token&&source.LastToken.IsCancellationRequested);}finally{caller.Cancel();try{await pending;}catch(OperationCanceledException){}}});});
await Check("cooperative private budget reports generic timeout rather than access denial",async()=>{var f=new Fixture();var source=new Source{Handler=async(tenant,ct)=>{await Task.Delay(Timeout.InfiniteTimeSpan,ct);return Status(tenant);}};await f.Run(async c=>{var e=await Expected<TimeoutException>(()=>Reader(source,TimeSpan.FromMilliseconds(100)).ReadAsync(c).AsTask());Require(e.Message=="The outbox status read exceeded its cooperative budget."&&e.InnerException is OperationCanceledException&&source.LastToken.IsCancellationRequested);});});
foreach(var cause in new[]{"timeout","caller","scope","both"})await Check("uncooperative source is awaited then late result withheld "+cause,async()=>
{var f=new Fixture();using var caller=new CancellationTokenSource();var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var tokenSignalled=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var source=new Source{Handler=async(tenant,ct)=>{using var registration=ct.Register(()=>tokenSignalled.TrySetResult());entered.TrySetResult();await release.Task;return Status(tenant);}};await f.Run(async c=>{var pending=Reader(source,cause is "timeout" or "both"?TimeSpan.FromMilliseconds(100):null).ReadAsync(c,caller.Token).AsTask();try{await entered.Task;if(cause is "timeout" or "both")await tokenSignalled.Task.WaitAsync(TimeSpan.FromSeconds(5));if(cause is "caller" or "both")caller.Cancel();if(cause=="scope")f.Clock.Advance(TimeSpan.FromMinutes(2));Require(!pending.IsCompleted);release.TrySetResult();if(cause=="timeout")await Expected<TimeoutException>(()=>pending);else if(cause=="scope")await Expected<TenantAccessDeniedException>(()=>pending);else Require((await Expected<OperationCanceledException>(()=>pending)).CancellationToken==caller.Token);}finally{release.TrySetResult();try{await pending;}catch(Exception){}}});Require(source.Calls==1);});
foreach(var withCaller in new[]{false,true})await Check("source IO fault is not masked by coincident cancellation or deadline "+withCaller,async()=>
{var f=new Fixture();using var caller=new CancellationTokenSource();var failure=new IOException("Controlled late source failure.");var source=new Source{Handler=async(_,ct)=>{var signalled=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);using var registration=ct.Register(()=>signalled.TrySetResult());if(withCaller)caller.Cancel();await signalled.Task;throw failure;}};await f.Run(async c=>{var e=await Expected<IOException>(()=>Reader(source,TimeSpan.FromMilliseconds(100)).ReadAsync(c,caller.Token).AsTask());Require(ReferenceEquals(e,failure));});});
await Check("independently scheduled reads stay independent and carry exact tenant",async()=>
{var f=new Fixture();var source=new Source{Handler=async(tenant,_)=>{await Task.Yield();return Status(tenant);}};var reader=Reader(source);var start=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);await f.Run(async c=>{var tasks=Enumerable.Range(0,16).Select(_=>Task.Run(async()=>{await start.Task;return await reader.ReadAsync(c);})).ToArray();start.TrySetResult();var results=await Task.WhenAll(tasks);Require(results.All(x=>x.Tenant.Value=="A")&&source.Calls==16&&source.Tenants.All(x=>x.Value=="A"));});});
await Check("one reader can serve separate fresh A and B contexts without a mutable current tenant",async()=>
{var a=new Fixture("A");var b=new Fixture("B");var source=new Source{Handler=async(tenant,_)=>{await Task.Yield();return Status(tenant);}};var reader=Reader(source);var start=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var tasks=new[]{Task.Run(()=>a.Run(async c=>{await start.Task;Require((await reader.ReadAsync(c)).Tenant.Value=="A");})),Task.Run(()=>b.Run(async c=>{await start.Task;Require((await reader.ReadAsync(c)).Tenant.Value=="B");}))};start.TrySetResult();await Task.WhenAll(tasks);Require(source.Calls==2&&source.Tenants.Select(x=>x.Value).Order().SequenceEqual(new[]{"A","B"}));});

Directory.CreateDirectory(Path.GetDirectoryName(output)!);await File.WriteAllTextAsync(output,JsonSerializer.Serialize(new{passed,failed,checks,scope="Portable checked aggregate-only status observation; no real database snapshot, hard timeout, provider/global freshness, supported host, benchmark or production qualification."},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"Outbox status contracts: {passed}/{passed+failed}");return failed==0?0:1;

sealed class Clock:TimeProvider{public DateTimeOffset Now=DateTimeOffset.Parse("2026-11-21T00:00:00Z");public long Timestamp;public override long TimestampFrequency=>TimeSpan.TicksPerSecond;public override DateTimeOffset GetUtcNow()=>Now;public override long GetTimestamp()=>Timestamp;public void Advance(TimeSpan duration){Now+=duration;Timestamp+=duration.Ticks;}}
sealed class Fixture:IIdentitySource,ITenantMembershipSource,IResourceScopeSource,ITenantAccessPolicy
{
 private readonly string tenant;private Func<TenantOperationContext,Task> body=_=>Task.CompletedTask;public Clock Clock{get;}=new();public TenantOperationRegistry Registry{get;}
 public Fixture(string tenant="A"){this.tenant=tenant;var builder=new TenantOperationRegistryBuilder();foreach(var op in new[]{("outbox.inspect","inspect","audit-outbox"),("custom.status","inspect","audit-outbox"),("outbox.relay","relay","audit-outbox"),("audit.history","read","audit-trail"),("document.update","write","document"),("inspect.wrong-kind","inspect","document"),("inspect.wrong-id","inspect","audit-outbox")})builder.Register<string,bool>(op.Item1,op.Item2,op.Item3,x=>x,x=>new(new(tenant),x),()=>new Handler(this));Registry=builder.Build();}
 public ValueTask<IdentitySnapshot?> ResolveAsync(CancellationToken ct)=>ValueTask.FromResult<IdentitySnapshot?>(new(new("issuer","service"),"fixture-service",Clock.Now.AddMinutes(-1),Clock.Now.AddMinutes(5)));
 public ValueTask<TenantMembershipSnapshot?> ResolveAsync(IdentitySnapshot identity,TenantId candidate,CancellationToken ct)=>ValueTask.FromResult<TenantMembershipSnapshot?>(candidate.Value==tenant?new(identity.Principal,candidate,true,Clock.Now.AddMinutes(-1),Clock.Now.AddMinutes(5),"membership"):null);
 public ValueTask<ResourceScopeSnapshot?> ResolveAsync(TenantId owner,string kind,string id,CancellationToken ct)=>ValueTask.FromResult<ResourceScopeSnapshot?>(new(owner,kind,id,"resource"));
 public ValueTask<bool> IsAllowedAsync(TenantAccessRequest request,CancellationToken ct)=>ValueTask.FromResult(true);
 public async Task Run(Func<TenantOperationContext,Task> callback,string operation="outbox.inspect"){Exception? callbackFailure=null;var reached=false;body=async context=>{reached=true;try{await callback(context);}catch(Exception error){callbackFailure=error;throw;}};var services=new TenantSecurityServices(this,new(["issuer"],["fixture-service"]),this,this,TimeSpan.FromMinutes(1),this,Clock);var result=await new TenantOperationDispatcher(Registry,services).DispatchAsync<string,bool>(operation,operation=="inspect.wrong-id"?"other":"tenant",new("owned-status-fixture"));if(callbackFailure is not null)System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(callbackFailure).Throw();if(!reached)throw new InvalidOperationException("Fixture did not reach the expected checked callback.");}
 private sealed class Handler(Fixture f):ITenantOperationHandler<string,bool>{public async ValueTask<OperationResult<bool>> HandleAsync(string request,TenantOperationContext context,CancellationToken ct){await f.body(context);return OperationResult<bool>.Success(true);}}
}
sealed class Source:ITenantChangeAuditOutboxStatusSource
{
 public int Calls;public CancellationToken LastToken;public ConcurrentBag<TenantId> Tenants{get;}=[];
 public Func<TenantId,CancellationToken,ValueTask<TenantChangeAuditOutboxStatus>> Handler=(tenant,_)=>ValueTask.FromResult(new TenantChangeAuditOutboxStatus(tenant,DateTimeOffset.Parse("2026-11-21T00:00:00Z"),3,2,1,1,4,DateTimeOffset.Parse("2026-11-20T23:59:00Z")));
 public ValueTask<TenantChangeAuditOutboxStatus> ReadAsync(TenantId tenant,CancellationToken token){Interlocked.Increment(ref Calls);Tenants.Add(tenant);LastToken=token;return Handler(tenant,token);}
}
